static std::unordered_set<std::string> normalize_ignore_words(const char* const* ignore_words, size_t ignore_words_length) {
    std::unordered_set<std::string> result;
    result.reserve(ignore_words_length);
    for (size_t i = 0; i < ignore_words_length; ++i) {
        const char* w = ignore_words[i];
