    return result;
}

struct HeapEntry {
    std::string word;
    uint64_t count;
};

struct HeapCompare {
    bool operator()(const HeapEntry& a, const HeapEntry& b) const {
        // return true if a is better than b (i.e., a should be below b in min-heap)
        if (a.count != b.count) return a.count > b.count;
        return a.word < b.word;
    }
};

static std::string read_whole_file(const std::string& path) {
    std::ifstream file(path, std::ios::binary);
    if (!file) throw std::runtime_error("Could not open input file: " + path);
    file.seekg(0, std::ios::end);
    std::streamsize size = file.tellg();
    if (size < 0) throw std::runtime_error("Could not determine input file size: " + path);
    file.seekg(0, std::ios::beg);
    std::string contents;
    contents.resize(static_cast<size_t>(size));
    if (size > 0) {
        file.read(&contents[0], size);
        if (!file) throw std::runtime_error("Could not read input file: " + path);
    }
    return contents;
}

extern "C" {

WordCount* top_words_from_file(
    const char* path,
    const char* const* ignore_words,
    size_t ignore_words_length,
    size_t max_results,
    size_t* result_length
) {
    if (result_length) *result_length = 0;
    if (!path || (ignore_words == nullptr && ignore_words_length != 0)) {
        return nullptr;
    }

    try {
        // Normalize ignore words into unordered_set
        std::unordered_set<std::string> ignore_set = normalize_ignore_words(ignore_words, ignore_words_length);

        // Read file
        std::string text = read_whole_file(path);

        // Count frequencies
        std::unordered_map<std::string, uint64_t> freq;
        freq.reserve(text.size() / 4); // rough estimate

        std::string current;
        current.reserve(32);
        for (char c : text) {
