                if (!current.empty() && ignore_set.find(current) == ignore_set.end()) {
                    ++freq[current];
                }
                current.clear();
            }
        }
        if (!current.empty() && ignore_set.find(current) == ignore_set.end()) {
            ++freq[current];
        }

        if (freq.empty() || max_results == 0) {
            return nullptr;
        }

        // Min-heap to keep top results
        std::priority_queue<HeapEntry, std::vector<HeapEntry>, HeapCompare> heap;
        heap = std::priority_queue<HeapEntry, std::vector<HeapEntry>, HeapCompare>(HeapCompare());

        for (auto& kv : freq) {
            const std::string& w = kv.first;
            uint64_t cnt = kv.second;
            if (heap.size() < max_results) {
                heap.push(HeapEntry{w, cnt});
            } else {
                const HeapEntry& top = heap.top();
                if (cnt > top.count || (cnt == top.count && w < top.word)) {
                    heap.pop();
                    heap.push(HeapEntry{w, cnt});
                }
            }
        }

        size_t result_size = heap.size();
        if (result_size == 0) return nullptr;

        WordCount* result = static_cast<WordCount*>(std::calloc(result_size, sizeof(WordCount)));
        if (!result) return nullptr;

        // Extract heap into vector then sort
        std::vector<HeapEntry> entries;
        entries.reserve(result_size);
        while (!heap.empty()) {
            entries.push_back(std::move(heap.top()));
            heap.pop();
        }
        // entries currently in ascending order of count (worst first). We need descending.
        std::sort(entries.begin(), entries.end(), [](const HeapEntry& a, const HeapEntry& b) {
            if (a.count != b.count) return a.count > b.count;
            return a.word < b.word;
        });

